// Glob matcher used by the label rules.
//
// Supported syntax:
//   *   - matches any run of characters within a single path segment (not "/")
//   ?   - matches exactly one non-"/" character
// We compile the glob to an anchored RegExp. Regex metacharacters in the
// literal portions are escaped so a pattern like "README.md" cannot have its
// "." act as a wildcard.

function escapeRegexLiteral(char: string): string {
  // Escape every char that is special in a RegExp.
  return char.replace(/[.+^${}()|[\]\\]/g, "\\$&");
}

export function globToRegExp(glob: string): RegExp {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i]!;
    if (c === "*") {
      re += "[^/]*";
    } else if (c === "?") {
      re += "[^/]";
    } else {
      re += escapeRegexLiteral(c);
    }
  }
  return new RegExp("^" + re + "$");
}

export function matchGlob(path: string, glob: string): boolean {
  return globToRegExp(glob).test(path);
}

